#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t = 1;
    vector<int> perm = {1, 2, 3, 4, 5, 6};
    vector<vector<int>> permutations_list;
    do {
        permutations_list.push_back(perm);
    } while (next_permutation(perm.begin(), perm.end()));

    int n;
    cin >> n;
    vector<int> a(3), b(3);
    for (int i = 0; i < 3; ++i) cin >> a[i];
    for (int i = 0; i < 3; ++i) cin >> b[i];

    int max_match = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);
    int max_result = 0;

    for (auto &perm : permutations_list) {
        vector<int> ta = a;
        vector<int> tb = b;
        int total = 0;
        for (int el : perm) {
            int t = 0;
            if (el == 1) {
                t = min(ta[0], tb[0]);
                ta[0] -= t;
                tb[0] -= t;
            } else if (el == 2) {
                t = min(ta[0], tb[2]);
                ta[0] -= t;
                tb[2] -= t;
            } else if (el == 3) {
                t = min(ta[1], tb[1]);
                ta[1] -= t;
                tb[1] -= t;
            } else if (el == 4) {
                t = min(ta[1], tb[0]);
                ta[1] -= t;
                tb[0] -= t;
            } else if (el == 5) {
                t = min(ta[2], tb[2]);
                ta[2] -= t;
                tb[2] -= t;
            } else if (el == 6) {
                t = min(ta[2], tb[1]);
                ta[2] -= t;
                tb[1] -= t;
            }
            total += t;
        }
        max_result = max(max_result, total);
    }

    cout << n - max_result << " " << max_match << "\n";

    return 0;
}
